const GLOSSARY = [
  ['SKU', 'Stock-keeping unit: one product code.'], ['GRN', 'Goods received note: the record of a delivery received.'], ['PO', 'Purchase order to a supplier.'], ['SO', 'Sales order from a customer.'],
  ['Putaway', 'Moving received goods from the dock into a storage location.'], ['FEFO', 'First-expiry-first-out: older-expiry batches are reserved and picked first.'],
  ['Reserved', 'Units promised to a confirmed order; not available for other orders.'], ['Quarantine', 'Units held for inspection; not sellable.'], ['In transit', 'Units dispatched on a transfer but not yet received.'],
  ['Ledger', 'The permanent, append-only list of every stock movement.'], ['Wave', 'A group of pick tasks picked together (batch or zone).'], ['Back-order', 'The part of an order that could not be reserved yet.'],
  ['3PL / storage client', 'A business whose goods you store and bill for storage and handling.'], ['NTN / STRN', 'Pakistan national tax number / sales tax registration number.'], ['Blind count', 'A count where the counter does not see the expected quantity.'],
];

const COMMON_FAQ = [
  ['Why can’t I see a menu or button?', 'Your role does not include that permission. Ask your administrator. Permissions are checked by the server.'],
  ['Can I edit or delete a posted stock movement?', 'No. History is permanent. Corrections are new transactions (an adjustment or reversal) with a reason, so the audit trail stays complete.'],
  ['Why does the screen say stock is not available?', 'It may be reserved for another order, in quarantine, damaged, expired, in transit or still at the receiving dock waiting for putaway.'],
  ['Is my data visible to other companies?', 'No. Every company’s data is isolated, and requests for another company’s records are refused.'],
];
const COMMON_TROUBLE = [
  ['“Missing anti-forgery header” or 403 when saving', 'Refresh the page. If it persists, you may lack permission for the action.'],
  ['Account locked', 'Too many wrong passwords. Wait a few minutes or ask your administrator to reset your password.'],
  ['Camera scanning does not start', 'Allow camera access for the site in the browser settings; use HTTPS; or type the code.'],
  ['Scanner types into the wrong field', 'Tap the scan box first. Most scanners act as a keyboard and send Enter after the code.'],
  ['Offline badge appears', 'Keep working on short tasks. Scans are queued and synced when the connection returns. Check Sync for conflicts.'],
];

